style.css:
@-moz-document url-prefix("http") {
/* Глобальные стили */
  * {
    /* Принудительно убираем фон, если он задан */
    background-color: transparent !important;
    /* Основной неоновый цвет текста */
    color: #39ff14 !important;
    /* Легкое свечение для создания неонового эффекта */
    text-shadow: 0 0 5px #00ffff !important;
    border-color: #39ff14 !important;
  }
  
  /* Фон страницы - градиент от глубокого синего к оранжевому закату */
  body {
    background: linear-gradient(to bottom, #001f3f, #FF4500) !important;
    font-family: 'Courier New', monospace !important;
  }
  
  /* Стили для ссылок */
  a {
    color: #39ff14 !important;
    text-shadow: 0 0 5px #00ffff !important;
  }
  
  a:hover {
    color: #FF4500 !important;
    text-shadow: 0 0 10px #00ffff !important;
  }
  
  /* Заголовки */
  h1, h2, h3, h4, h5, h6 {
    color: #FF4500 !important;
    text-shadow: 0 0 5px #39ff14 !important;
  }
  
  /* Кнопки и элементы управления */
  button, input[type="button"], input[type="submit"] {
    background: linear-gradient(45deg, #001f3f, #FF4500) !important;
    border: 2px solid #39ff14 !important;
    color: #ffffff !important;
    text-shadow: 0 0 5px #00ffff !important;
    cursor: pointer;
  }
  
  /* Поля ввода, textarea, select */
  input, textarea, select {
    background-color: #1a1a1a !important;
    color: #39ff14 !important;
    border: 1px solid #39ff14 !important;
  }
  
  /* Изображения немного затемняем для общего тона */
  img {
    opacity: 0.9;
  }
  
  /* Кастомизация скроллбаров для браузеров на основе Webkit */
  ::-webkit-scrollbar {
    width: 12px;
  }
  
  ::-webkit-scrollbar-track {
    background: #001f3f;
  }
  
  ::-webkit-scrollbar-thumb {
    background-color: #FF4500;
    border-radius: 10px;
    border: 3px solid #001f3f;
  }
}
